const SimpleTrendChart = ({ data }: { data: any[] }) => {
    if (!data.length) return <div className="h-full w-full flex items-center justify-center text-slate-500 text-xs">No Data</div>;
    const max = Math.max(...data.map(d => Math.max(d.success, d.error)), 1);

    // Create points string
    const successPoints = data.map((d, i) => {
        const x = (i / (data.length - 1)) * 100;
        const y = 100 - (d.success / max) * 100;
        return `${x},${y}`;
    }).join(' ');

    const errorPoints = data.map((d, i) => {
        const x = (i / (data.length - 1)) * 100;
        const y = 100 - (d.error / max) * 100;
        return `${x},${y}`;
    }).join(' ');

    return (
      <div className="relative h-full w-full overflow-hidden pb-6 pl-2 pt-2">
          {/* Grid lines */}
          <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-6">
              {[0, 0.25, 0.5, 0.75, 1].map((n) => (
                  <div key={n} className="w-full h-px bg-slate-800/50"></div>
              ))}
          </div>

          <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="w-full h-full overflow-visible">
              {/* Success Line */}
              <defs>
                  <linearGradient id="successGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                      <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
              </defs>
              <polygon points={`0,100 ${successPoints} 100,100`} fill="url(#successGradient)" />
              <polyline points={successPoints} fill="none" stroke="#10b981" strokeWidth="2" vectorEffect="non-scaling-stroke" />

              {/* Error Line */}
              <polyline points={errorPoints} fill="none" stroke="#ef4444" strokeWidth="2" strokeDasharray="4" vectorEffect="non-scaling-stroke" />

              {/* Dots */}
              {data.map((d, i) => {
                   const x = (i / (data.length - 1)) * 100;
                   const yS = 100 - (d.success / max) * 100;
                   const yE = 100 - (d.error / max) * 100;
                   return (
                       <g key={i}>
                           <circle cx={x} cy={yS} r="1.5" className="fill-slate-900 stroke-vibrant-green stroke-2 hover:r-3 transition-all cursor-pointer">
                               <title>{`${d.date} - Success: ${d.success}`}</title>
                           </circle>
                           {d.error > 0 && (
                                <circle cx={x} cy={yE} r="1.5" className="fill-slate-900 stroke-red-500 stroke-2 hover:r-3 transition-all cursor-pointer">
                                    <title>{`${d.date} - Error: ${d.error}`}</title>
                                </circle>
                           )}
                       </g>
                   )
              })}
          </svg>
          <div className="absolute bottom-0 w-full flex justify-between px-0 text-[10px] text-slate-500 font-mono">
              <span>{data[0]?.date}</span>
              <span>{data[Math.floor(data.length/2)]?.date}</span>
              <span>{data[data.length - 1]?.date}</span>
          </div>
      </div>
    )
}

