export const DemoSection: React.FC<DemoSectionProps> = ({ currentUser, onOpenAuth, language, setLanguage, initialPrompt, startTour, onTourComplete }) => {
  // State
  const [activeAgentId, setActiveAgentId] = useState<string>('sales');
  const [customAgents, setCustomAgents] = useState<typeof AGENT_CATALOG>([]);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [showIntegrations, setShowIntegrations] = useState(false);
  const [isNicheMode, setIsNicheMode] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // App Selection & File Import State
  const [selectedIntegrations, setSelectedIntegrations] = useState<string[]>([]);
  const [attachedFiles, setAttachedFiles] = useState<AttachedFile[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Dashboard State
  const [showDashboard, setShowDashboard] = useState(false);
  const [dashboardView, setDashboardView] = useState<'overview' | 'analytics' | 'subscriptions' | 'billing' | 'compliance' | 'workflow-detail'>('overview');
  const [selectedWorkflowDetail, setSelectedWorkflowDetail] = useState<WorkflowLog | null>(null);

  // Advanced Analytics State for Workflow Detail
  const [workflowDateRange, setWorkflowDateRange] = useState<'7D' | '30D' | 'Custom'>('7D');
  const [taskValue, setTaskValue] = useState<number>(50); // Default custom value per run

  // Visual Editor State
  const [showVisualEditor, setShowVisualEditor] = useState(false);
  const [editorData, setEditorData] = useState<WorkflowDefinition | null>(null);
  const [selectedStepIndex, setSelectedStepIndex] = useState<number | null>(null);

  // Data State
  const [workflowHistory, setWorkflowHistory] = useState<WorkflowLog[]>([]);
  const [timeFilter, setTimeFilter] = useState<'Daily' | 'Weekly' | 'Monthly'>('Monthly');

  // UI State
  const [notification, setNotification] = useState<{type: 'success' | 'error' | 'info', message: string} | null>(null);
  const [showCreateAgentModal, setShowCreateAgentModal] = useState(false);
  const [newAgentData, setNewAgentData] = useState({ name: '', role: '' });
  const [showVideoCall, setShowVideoCall] = useState(false);
  const [callDuration, setCallDuration] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  // Voice State
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Tour State
  const [isTourOpen, setIsTourOpen] = useState(false);

  // Refs
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatHistoryRef = useRef<any>([]); // Stores gemini history format

  const activeAgent = useMemo(() => {
    return [...AGENT_CATALOG, ...customAgents].find(a => a.id === activeAgentId) || AGENT_CATALOG[0];
  }, [activeAgentId, customAgents]);

  const uiText = DEMO_TRANSLATIONS[language] || DEMO_TRANSLATIONS['English'];

  // --- EFFECTS ---

  // Initialize Mock Data
  useEffect(() => {
    setWorkflowHistory(generateMockHistory());
  }, []);

  // Lock scroll when integrations modal is open
  useEffect(() => {
    if (showIntegrations) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [showIntegrations]);

  // Handle Tour Trigger
  useEffect(() => {
    if (startTour) {
        // Ensure dashboard is closed so elements are visible
        setShowDashboard(false);
        // Ensure sidebar is open on mobile if needed (optional logic)
        setIsTourOpen(true);
    }
  }, [startTour]);

  // Handle Video Call Timer
  useEffect(() => {
      let interval: any;
      if (showVideoCall) {
          interval = setInterval(() => setCallDuration(prev => prev + 1), 1000);
      } else {
          setCallDuration(0);
      }
      return () => clearInterval(interval);
  }, [showVideoCall]);

  // Handle Initial Prompt from Gallery or other sections
  useEffect(() => {
    if (initialPrompt && !isProcessing) {
        // Reset state for new analysis
        setShowDashboard(false);
        setActiveAgentId('sales'); 
        setMessages([]);
        chatHistoryRef.current = [];
        executeWorkflowGeneration(initialPrompt);
    }
  }, [initialPrompt]);

  // CRITICAL: Context Reset on Agent Switch
  useEffect(() => {
    if (!showDashboard) {
        setMessages([]); // Clear chat history
        setInput('');
        setShowIntegrations(false);
        setSelectedIntegrations([]); // Reset selections
        setAttachedFiles([]); // Reset files
        chatHistoryRef.current = []; // Clear AI history
        setIsNicheMode(false); // Reset niche mode
        // Instant scroll to top to show Welcome Message
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = 0;
        }
        setIsMobileMenuOpen(false);
    }
  }, [activeAgentId, showDashboard]);

  // Scroll on new message
  useEffect(() => {
     if (messages.length > 0 && chatContainerRef.current) {
         chatContainerRef.current.scrollTo({
             top: chatContainerRef.current.scrollHeight,
             behavior: 'smooth'
         });
     }
  }, [messages]);

  // --- ACTIONS ---

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const handleTourComplete = () => {
      setIsTourOpen(false);
      if (onTourComplete) onTourComplete();
      showNotification('success', 'You are ready to automate!');
  };

  const showNotification = (type: 'success' | 'error' | 'info', message: string) => {
      setNotification({ type, message });
      setTimeout(() => setNotification(null), 3000);
  };

  const handleLanguageChange = (lang: string) => {
    setLanguage(lang);
    showNotification('success', `Language changed successfully to ${lang}. UI updated.`);
  };

  const stopListening = () => {
    if (recognitionRef.current) {
      try {
        recognitionRef.current.stop();
      } catch (e) {
        console.warn("Error stopping recognition:", e);
      }
      recognitionRef.current = null;
    }
    setIsListening(false);
  };

  const startListening = () => {
    if (isListening) {
      stopListening();
      return;
    }

    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

      stopListening();

      const recognition = new SpeechRecognition();
      recognitionRef.current = recognition;

      recognition.lang = language === 'Hindi' ? 'hi-IN' : language === 'Bengali' ? 'bn-IN' : 'en-US';
      recognition.interimResults = false;
      recognition.maxAlternatives = 1;

      recognition.onstart = () => {
        setIsListening(true);
        showNotification('info', 'Listening... Please speak now.');
      };

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(transcript);
        stopListening();
      };

      recognition.onerror = (event: any) => {
        if (event.error === 'aborted') {
            setIsListening(false);
            return;
        }
        if (event.error === 'no-speech') {
             stopListening();
             showNotification('info', 'No speech detected.');
             return;
        }
        console.error("Speech recognition error", event.error);
        stopListening();
        showNotification('error', 'Voice input failed. Please type.');
      };

      recognition.onend = () => {
          if (isListening) {
             setIsListening(false);
          }
      }

      try {
          recognition.start();
      } catch (e) {
          console.error("Failed to start recognition", e);
          stopListening();
      }
    } else {
      showNotification('info', 'Voice input not supported in this browser.');
    }
  };

  const toggleIntegrationSelection = (toolName: string) => {
      if (selectedIntegrations.includes(toolName)) {
          setSelectedIntegrations(prev => prev.filter(t => t !== toolName));
      } else {
          if (selectedIntegrations.length >= 5) {
              showNotification('info', 'You can select up to 5 apps for a workflow.');
              return;
          }
          setSelectedIntegrations(prev => [...prev, toolName]);
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newFile: AttachedFile = {
              name: file.name,
              size: (file.size / 1024).toFixed(1) + ' KB',
              type: file.name.endsWith('.pdf') ? 'pdf' : file.name.endsWith('.csv') ? 'csv' : 'image'
          };
          setAttachedFiles(prev => [...prev, newFile]);
          showNotification('success', `Attached ${file.name}`);
      }
  };

  const removeFile = (index: number) => {
      setAttachedFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleCreateAgent = () => {
      if (!newAgentData.name) return;
      const newId = `custom-${Date.now()}`;
      setCustomAgents([...customAgents, {
          id: newId,
          name: newAgentData.name,
          role: newAgentData.role || 'Custom Automation Agent',
          model: 'gemini-3-pro-preview',
          icon: Bot,
          color: 'text-white',
          bgColor: 'bg-white/10'
      }]);
      setShowCreateAgentModal(false);
      setNewAgentData({ name: '', role: '' });
      setActiveAgentId(newId);
      showNotification('success', `Created ${newAgentData.name} successfully!`);
  };

  const executeWorkflowGeneration = async (promptText: string) => {
    if (!promptText.trim()) return;

    let contextPrompt = promptText;
    if (selectedIntegrations.length > 0) {
        contextPrompt += `\n\n[USER CONTEXT] Selected Apps to Integrate: ${selectedIntegrations.join(', ')}.`;
    }
    if (attachedFiles.length > 0) {
        contextPrompt += `\n\n[USER CONTEXT] Analyzed Uploaded Files: ${attachedFiles.map(f => f.name).join(', ')}.`;
    }

    const userMsg: ChatMessage = { role: 'user', text: promptText, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
        // DETECT NICHE ANALYSIS VS WORKFLOW
        const isNicheStart = promptText.includes("Deep Niche Analysis") || promptText.includes("operate in the following sectors") || promptText.includes("sector");

        // Maintain Niche Mode if already in it, or if starting it.
        if (isNicheStart || isNicheMode) {
             if (isNicheStart) setIsNicheMode(true);

             // Use Conversational Chat Mode with specific instruction for Niche Analysis
             const responseText = await chatWithBot(
                 chatHistoryRef.current, 
                 contextPrompt, 
                 activeAgent.model, 
                 language,
                 NICHE_ANALYSIS_SYSTEM_PROMPT
             );

             // Check if response contains JSON (Final Step of Niche Analysis)
             let workflowData: WorkflowDefinition | undefined;
             const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/);
             let displayText = responseText;

             if (jsonMatch) {
                try {
                    workflowData = JSON.parse(jsonMatch[1]);
                    // Remove the JSON from the text displayed to the user
                    displayText = responseText.replace(jsonMatch[0], "").trim();
                    // Optionally turn off Niche mode after success, or keep it for follow-up
                    // setIsNicheMode(false); 
                } catch (e) {
                    console.error("Failed to parse workflow JSON from chat", e);
                }
             }

             // Update history (AI History stores the full text including JSON)
             chatHistoryRef.current.push({ role: 'user', parts: [{ text: contextPrompt }] });
             chatHistoryRef.current.push({ role: 'model', parts: [{ text: responseText }] });

             const botMsg: ChatMessage = {
                 role: 'model',
                 text: displayText,
                 workflowData: workflowData,
                 timestamp: Date.now()
             };
             setMessages(prev => [...prev, botMsg]);
        } else {
             // Use Workflow Generation Mode (JSON)
             showNotification('info', 'Agent is building workflow...');
             const workflow = await generateAgenticWorkflow(contextPrompt, language);

             const botMsg: ChatMessage = {
                 role: 'model',
                 text: workflow.user_intent_summary,
                 workflowData: workflow,
                 timestamp: Date.now()
             };
             setMessages(prev => [...prev, botMsg]);
        }

        if (selectedIntegrations.length > 0) setSelectedIntegrations([]);
        if (attachedFiles.length > 0) setAttachedFiles([]);

    } catch (error) {
        showNotification('error', 'Failed to process request.');
        console.error(error);
    } finally {
        setIsProcessing(false);
    }
  };

  const handleApproveRun = (workflow: WorkflowDefinition) => {
      showNotification('success', 'Workflow executed successfully!');

      const newLog: WorkflowLog = {
          id: `run-${Date.now()}`,
          workflowName: workflow.workflow_name,
          agentId: activeAgentId,
          timestamp: Date.now(),
          status: 'Success',
          timeSavedMinutes: 25,
          appsUsed: workflow.actions.map(a => a.app)
      };

      setWorkflowHistory(prev => [newLog, ...prev]);

      setMessages(prev => [...prev, {
          role: 'model',
          text: `✅ **Success!** ${workflow.workflow_name} has been completed.`,
          timestamp: Date.now()
      }]);
  };

  const deleteWorkflowLog = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      setWorkflowHistory(prev => prev.filter(log => log.id !== id));
      showNotification('info', 'Workflow log deleted.');
  };

  const handleWorkflowClick = (log: WorkflowLog) => {
      setSelectedWorkflowDetail(log);
      setDashboardView('workflow-detail');
  };

  const openVisualEditor = (data: WorkflowDefinition) => {
      setEditorData(data);
      setShowVisualEditor(true);
      setSelectedStepIndex(null); 
  };

  const handleSaveEditor = () => {
      showNotification('success', 'Workflow changes saved successfully.');
      setShowVisualEditor(false);
  };

  // --- EDITOR HELPERS ---
  const handleEditorTriggerChange = (field: string, value: string) => {
      if (!editorData) return;
      setEditorData({
          ...editorData,
          trigger: { ...editorData.trigger, [field]: value }
      });
  };

  const handleEditorActionChange = (index: number, field: string, value: string) => {
      if (!editorData) return;
      const newActions = [...editorData.actions];
      newActions[index] = { ...newActions[index], [field]: value };
      setEditorData({ ...editorData, actions: newActions });
  };

  const handleAddStep = () => {
      if (!editorData) return;
      setEditorData({
          ...editorData,
          actions: [
              ...editorData.actions,
              { app: "System", action_type: "Configure Action", instructions: "Define action logic...", auto_integration: true }
          ]
      });
  };

  const handleRemoveStep = (index: number) => {
      if (!editorData) return;
      const newActions = [...editorData.actions];
      newActions.splice(index, 1);
      setEditorData({ ...editorData, actions: newActions });
      if (selectedStepIndex === index) setSelectedStepIndex(null);
  };

  // --- DASHBOARD HELPERS ---

  const getDashboardStats = useMemo(() => {
      const now = Date.now();
      let limit = now;
      let dateFormat: Intl.DateTimeFormatOptions = { day: 'numeric', month: 'short' };

      if (timeFilter === 'Daily') {
        limit = now - (24 * 60 * 60 * 1000);
        dateFormat = { hour: 'numeric', hour12: true };
      }
      else if (timeFilter === 'Weekly') {
         limit = now - (7 * 24 * 60 * 60 * 1000);
         dateFormat = { weekday: 'short' };
      }
      else if (timeFilter === 'Monthly') {
         limit = now - (30 * 24 * 60 * 60 * 1000);
         dateFormat = { day: 'numeric', month: 'short' };
      }

      const filteredLogs = workflowHistory.filter(l => l.timestamp >= limit);

      const totalRuns = filteredLogs.length;
      const successRuns = filteredLogs.filter(l => l.status === 'Success').length;
      const failedRuns = totalRuns - successRuns;
      const completionRate = totalRuns > 0 ? ((successRuns / totalRuns) * 100).toFixed(1) : "0.0";
      const totalTimeSaved = filteredLogs.reduce((acc, curr) => acc + curr.timeSavedMinutes, 0);
      const avgTimeSaved = totalRuns > 0 ? Math.round(totalTimeSaved / totalRuns) : 0;

      // Estimated Cost Saved (Assumption: ₹500/hr manual labor cost)
      const estimatedCostSaved = Math.round((totalTimeSaved / 60) * 500);

      // --- Advanced Analytics Data Prep ---

      // 1. Agent Performance (Stacked Bar)
      const agentPerformanceMap: Record<string, {name: string, success: number, failed: number}> = {};
      filteredLogs.forEach(log => {
          const agent = [...AGENT_CATALOG, ...customAgents].find(a => a.id === log.agentId);
          const name = agent ? agent.name.split(' ')[0] : 'Unknown'; 

          if (!agentPerformanceMap[name]) agentPerformanceMap[name] = { name, success: 0, failed: 0 };

          if (log.status === 'Success') agentPerformanceMap[name].success++;
          else agentPerformanceMap[name].failed++;
      });
      const agentPerformanceData = Object.values(agentPerformanceMap);

      // 2. Trend Analysis (Area Chart)
      const trendMap: Record<string, { name: string, runs: number, success: number }> = {};

      filteredLogs.forEach(log => {
          const date = new Date(log.timestamp);
          const label = date.toLocaleDateString('en-US', dateFormat);

          if (!trendMap[label]) trendMap[label] = { name: label, runs: 0, success: 0 };
          trendMap[label].runs++;
          if (log.status === 'Success') trendMap[label].success++;
      });

      const trendData = Object.values(trendMap).reverse(); 

      // 3. Top Workflows by ROI (Time Saved)
      const workflowRoiMap: Record<string, { name: string, timeSaved: number, runs: number }> = {};
      filteredLogs.forEach(log => {
          const name = log.workflowName;
          if (!workflowRoiMap[name]) workflowRoiMap[name] = { name, timeSaved: 0, runs: 0 };
          workflowRoiMap[name].timeSaved += log.timeSavedMinutes;
          workflowRoiMap[name].runs++;
      });
      const topWorkflowsData = Object.values(workflowRoiMap)
          .sort((a,b) => b.timeSaved - a.timeSaved)
          .slice(0, 5); 

      // 4. Task Distribution (Pie) based on Agent Role/Type
      const agentTypeMap: Record<string, number> = {};
      filteredLogs.forEach(log => {
          const agent = [...AGENT_CATALOG, ...customAgents].find(a => a.id === log.agentId);
          const type = agent ? agent.name : 'Other';
          agentTypeMap[type] = (agentTypeMap[type] || 0) + 1;
      });

      const pieData = Object.keys(agentTypeMap).map((key, index) => ({
          name: key,
          value: agentTypeMap[key],
          color: ['#10b981', '#3b82f6', '#f97316', '#8b5cf6', '#ec4899', '#facc15'][index % 6]
      }));


      return { 
          totalRuns, 
          successRuns, 
          failedRuns, 
          completionRate, 
          totalTimeSaved, 
          avgTimeSaved,
          estimatedCostSaved, 
          filteredLogs,
          agentPerformanceData,
          trendData,
          topWorkflowsData,
          pieData
      };
  }, [workflowHistory, timeFilter, customAgents]); 

  // Specific Analytics for a selected workflow detail view
  const getWorkflowStats = useMemo(() => {
     if (!selectedWorkflowDetail) return null;

     const now = Date.now();
     let rangeMs = 7 * 24 * 60 * 60 * 1000;
     if (workflowDateRange === '30D') rangeMs = 30 * 24 * 60 * 60 * 1000;
     if (workflowDateRange === 'Custom') rangeMs = 90 * 24 * 60 * 60 * 1000; // Mock 90 days

     // Filter logs for THIS specific workflow name within date range
     const specificLogs = workflowHistory.filter(l => 
         l.workflowName === selectedWorkflowDetail.workflowName &&
         l.timestamp >= (now - rangeMs)
     );

     const totalExecutions = specificLogs.length || 1; // Prevent div/0
     const successCount = specificLogs.filter(l => l.status === 'Success').length;
     const successRate = ((successCount / totalExecutions) * 100).toFixed(1);

     // ROI Calculations
     const costPerRun = 0.5; // Mock API cost in Rupees
     const totalCost = totalExecutions * costPerRun;
     const totalValue = successCount * taskValue; // Use custom task value
     const roi = totalCost > 0 ? ((totalValue - totalCost) / totalCost) * 100 : 0;

     // Trend Data for Line Chart
     const trendMap: Record<string, { date: string, success: number, error: number }> = {};
     specificLogs.forEach(log => {
         const dateKey = new Date(log.timestamp).toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
         if(!trendMap[dateKey]) trendMap[dateKey] = { date: dateKey, success: 0, error: 0 };
         if (log.status === 'Success') trendMap[dateKey].success++;
         else trendMap[dateKey].error++;
     });
     const trendData = Object.values(trendMap).reverse();

     // Input Analysis Mock Data (based on simulated inputs)
     const inputAnalysisData = [
         { name: 'Google Ads', value: 85, color: 'bg-blue-500' },
         { name: 'Facebook', value: 65, color: 'bg-blue-400' },
         { name: 'Manual Entry', value: 95, color: 'bg-green-500' },
         { name: 'Email', value: 78, color: 'bg-purple-500' }
     ];

     return {
         totalExecutions,
         successRate,
         avgTime: '1.2s', // Mock constant for now
         roi: roi.toFixed(0),
         costPerRun,
         valuePerRun: taskValue,
         trendData: trendData.length ? trendData : [{ date: 'Today', success: 0, error: 0 }],
         inputAnalysisData,
         logs: specificLogs
     };

  }, [selectedWorkflowDetail, workflowHistory, workflowDateRange, taskValue]);

  const stats = getDashboardStats;
  const wfStats = getWorkflowStats;

  // --- RENDERERS ---

  const renderDashboardMenu = () => (
      <div className="space-y-2 px-4 py-4">
          <div className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2 px-2">Dashboard Menu</div>
          {[
              { id: 'overview', label: uiText.overview, icon: LayoutDashboard },
              { id: 'analytics', label: uiText.deepAnalytics, icon: BarChart3 },
              { id: 'subscriptions', label: uiText.subscriptions, icon: CreditCard },
              { id: 'billing', label: uiText.billing, icon: Receipt },
              { id: 'compliance', label: uiText.compliance, icon: ShieldCheck },
          ].map(item => (
              <button
                  key={item.id}
                  onClick={() => {
                      setDashboardView(item.id as any);
