const SimpleAreaChart = ({ data }: { data: any[] }) => {
  if (!data.length) return <div className="h-full w-full flex items-center justify-center text-slate-500 text-xs">No Data</div>;
  const max = Math.max(...data.map(d => d.runs), 1);
  const points = data.map((d, i) => {
    const x = (i / (data.length - 1)) * 100;
    const y = 100 - (d.runs / max) * 100;
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className="relative h-full w-full overflow-hidden pb-6 pl-2">
        <div className="absolute left-2 top-0 bottom-6 w-px bg-slate-800"></div>
        <div className="absolute left-2 bottom-6 right-0 h-px bg-slate-800"></div>
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="w-full h-full overflow-visible">
            <defs>
                <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                </linearGradient>
            </defs>
            <polygon points={`0,100 ${points} 100,100`} fill="url(#areaGradient)" />
            <polyline points={points} fill="none" stroke="#3b82f6" strokeWidth="2" vectorEffect="non-scaling-stroke" />
            {data.map((d, i) => {
                 const x = (i / (data.length - 1)) * 100;
                 const y = 100 - (d.runs / max) * 100;
                 return (
                     <circle key={i} cx={x} cy={y} r="1.5" className="fill-blue-500 stroke-slate-900 stroke-2 hover:r-3 transition-all cursor-pointer">
                         <title>{`${d.name}: ${d.runs} Runs`}</title>
                     </circle>
                 )
            })}
        </svg>
        <div className="absolute bottom-0 w-full flex justify-between px-0 text-[10px] text-slate-500">
            <span>{data[0]?.name}</span>
            <span>{data[data.length - 1]?.name}</span>
        </div>
    </div>
  )
}

const SimplePieChart = ({ data }: { data: any[] }) => {
   const total = data.reduce((acc, curr) => acc + curr.value, 0);
   let currentAngle = 0;

   return (
     <div className="relative h-full w-full flex items-center justify-center gap-8">
         <div className="w-40 h-40 relative">
            <svg viewBox="0 0 100 100" className="w-full h-full -rotate-90">
                {data.map((d, i) => {
                    const angle = (d.value / total) * 360;
                    if (angle === 0) return null;

                    const x1 = 50 + 50 * Math.cos(Math.PI * currentAngle / 180);
                    const y1 = 50 + 50 * Math.sin(Math.PI * currentAngle / 180);
                    const x2 = 50 + 50 * Math.cos(Math.PI * (currentAngle + angle) / 180);
                    const y2 = 50 + 50 * Math.sin(Math.PI * (currentAngle + angle) / 180);
                    const largeArc = angle > 180 ? 1 : 0;

                    const path = total === d.value 
                        ? `M 50 50 m -50, 0 a 50,50 0 1,0 100,0 a 50,50 0 1,0 -100,0` 
                        : `M 50 50 L ${x1} ${y1} A 50 50 0 ${largeArc} 1 ${x2} ${y2} Z`;

                    const slice = (
                        <path 
                            key={i} 
                            d={path} 
                            fill={d.color} 
                            stroke="#0f172a" 
                            strokeWidth="1"
                            className="hover:opacity-90 transition-opacity cursor-pointer"
                        >
                            <title>{`${d.name}: ${d.value}`}</title>
                        </path>
                    );
                    currentAngle += angle;
                    return slice;
                })}
                <circle cx="50" cy="50" r="30" fill="#0f172a" />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <span className="text-xl font-bold text-white">{total}</span>
            </div>
         </div>

         <div className="flex flex-col justify-center gap-2 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
             {data.map((d, i) => (
                 <div key={i} className="flex items-center gap-2 text-xs">
                     <div className="w-3 h-3 rounded-full flex-shrink-0" style={{backgroundColor: d.color}}></div>
                     <span className="text-slate-300 whitespace-nowrap">{d.name} <span className="text-slate-500">({Math.round(d.value/total*100)}%)</span></span>
                 </div>
             ))}
         </div>
     </div>
   )
}

