// --- HELPER: MOCK HISTORY ---

const generateMockHistory = (): WorkflowLog[] => {
    const logs: WorkflowLog[] = [];
    const now = Date.now();
    const day = 24 * 60 * 60 * 1000;

    // Generate data for the last 30 days
    for (let i = 0; i < 30; i++) {
        const isToday = i === 0;
        const count = isToday ? 8 : Math.floor(Math.random() * 8) + 3; // More variation

        for(let j=0; j<count; j++) {
            const agentId = ['sales', 'operations', 'marketing', 'tax', 'hr', 'support'][Math.floor(Math.random() * 6)];
            const status = Math.random() > 0.15 ? 'Success' : 'Failed';

            logs.push({
                id: `log-${i}-${j}-${Math.random()}`,
                workflowName: [
                    "Sync Shopify Orders to Zoho CRM",
                    "Draft Cold Email Sequence for Tech Startups",
                    "Generate Invoice for Acme Corp using Vyapar", 
                    "Send WhatsApp Follow-up to Leads",
                    "Update Inventory in Tally Prime",
                    "Calculate GST for October",
                    "Schedule Candidate Interviews",
                    "Respond to Support Ticket #1023",
                    "Analyze Weekly Sales Report",
                    "Create Marketing Campaign for Diwali"
                ][Math.floor(Math.random() * 10)],
                agentId: agentId,
                timestamp: now - (i * day) - (Math.random() * day),
                status: status,
                timeSavedMinutes: 10 + Math.floor(Math.random() * 110), // 10 to 120 mins
                appsUsed: [['sales', 'gmail'], ['whatsapp', 'sheets'], ['tally', 'gmail'], ['shopify', 'zoho'], ['slack', 'trello']][Math.floor(Math.random() * 5)]
            });
        }
    }
    return logs.sort((a,b) => b.timestamp - a.timestamp);
};

