                                {/* Header */}
                                <div className="p-5 border-b border-slate-800 flex justify-between items-center bg-[#0f172a] shrink-0">
                                    <div>
                                        <h3 className="text-xl font-bold text-white flex items-center gap-2">
                                            <LayoutGrid className="w-6 h-6 text-vibrant-orange" /> 
                                            {uiText.appsLibrary}
                                        </h3>
                                        <p className="text-sm text-slate-400 mt-1">Connect your favorite tools to automate workflows.</p>
                                    </div>
                                    <button 
                                      onClick={() => setShowIntegrations(false)} 
                                      className="text-slate-400 hover:text-white p-2 rounded-xl hover:bg-slate-800 transition-colors"
                                    >
                                        <X className="w-6 h-6" />
                                    </button>
                                </div>

                                {/* Search Bar & Categories */}
                                <div className="p-4 border-b border-slate-800 bg-slate-900/50 shrink-0 flex flex-col gap-3">
                                    <div className="relative">
                                        <Search className="absolute left-3 top-3 w-5 h-5 text-slate-500" />
                                        <input 
                                          type="text" 
                                          value={searchQuery}
                                          onChange={(e) => setSearchQuery(e.target.value)}
                                          placeholder="Search 100+ apps (e.g. Gmail, Slack, Tally)..." 
                                          className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 pl-10 pr-4 text-white focus:border-vibrant-green outline-none transition-all placeholder:text-slate-600"
                                        />
                                    </div>
                                    {/* Horizontal Category Scroll */}
                                    <div className="flex gap-2 overflow-x-auto pb-1 custom-scrollbar scroll-smooth">
                                        {INTEGRATION_CATEGORIES.map(cat => (
                                            <button 
                                                key={cat.name}
                                                onClick={() => scrollToCategory(cat.name)}
                                                className="whitespace-nowrap px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs font-medium text-slate-300 hover:text-white transition-colors"
                                            >
                                                {cat.name}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                {/* Content */}
                                <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar bg-[#0b1120]">
                                      {INTEGRATION_CATEGORIES.map((category) => {
                                          const filteredTools = category.tools.filter(t => t.toLowerCase().includes(searchQuery.toLowerCase()));
                                          if (filteredTools.length === 0) return null;

                                          return (
                                              <div key={category.name} id={`category-${category.name}`} className="animate-in slide-in-from-bottom-2 scroll-mt-4">
                                                  <h5 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-4 pl-1 border-b border-slate-800 pb-2 flex items-center gap-2">
                                                      {category.name}
                                                      <span className="bg-slate-800 text-slate-400 px-1.5 py-0.5 rounded-full text-[10px]">{filteredTools.length}</span>
                                                  </h5>
                                                  <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
                                                      {filteredTools.map(tool => {
                                                          const meta = TOOL_METADATA[tool] || { desc: "Integration", icon: LayoutGrid };
                                                          const Icon = meta.icon || LayoutGrid;
                                                          const isSelected = selectedIntegrations.includes(tool);
                                                          return (
                                                              <button 
                                                                  key={tool}
                                                                  onClick={() => toggleIntegrationSelection(tool)}
                                                                  className={`p-4 rounded-xl text-left transition-all flex flex-col justify-between group h-28 border relative overflow-hidden ${
                                                                      isSelected
                                                                      ? 'bg-vibrant-green/10 border-vibrant-green text-white shadow-lg shadow-green-900/20'
                                                                      : 'bg-slate-800/50 border-slate-700/50 text-slate-400 hover:bg-slate-800 hover:text-white hover:border-slate-600 hover:shadow-md'
                                                                  }`}
                                                              >
                                                                  <div className="flex justify-between items-start w-full mb-2 relative z-10">
                                                                      <div className={`p-2 rounded-lg ${isSelected ? 'bg-vibrant-green text-navy-900' : 'bg-slate-900 text-slate-500 group-hover:text-slate-300'} transition-colors`}>
                                                                         <Icon className="w-5 h-5 shrink-0" />
                                                                      </div>
                                                                      {isSelected && (
                                                                          <div className="bg-vibrant-green text-navy-900 p-1 rounded-full animate-in zoom-in">
                                                                              <Check className="w-3 h-3 shrink-0" />
                                                                          </div>
                                                                      )}
                                                                  </div>
                                                                  <div className="relative z-10">
                                                                      <span className="text-sm font-bold truncate block mb-0.5">{tool}</span>
                                                                      <span className={`text-[10px] truncate block ${isSelected ? 'text-green-200' : 'text-slate-600 group-hover:text-slate-500'}`}>{meta.desc}</span>
                                                                  </div>
                                                                  {/* Hover Glow */}
                                                                  <div className="absolute inset-0 bg-gradient-to-tr from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>
                                                              </button>
                                                          )
                                                      })}
                                                  </div>
                                              </div>
                                          )
                                      })}
                                      {INTEGRATION_CATEGORIES.every(c => c.tools.every(t => !t.toLowerCase().includes(searchQuery.toLowerCase()))) && (
                                          <div className="text-center py-20">
                                              <Search className="w-12 h-12 text-slate-700 mx-auto mb-4" />
                                              <p className="text-slate-500">No apps found matching "{searchQuery}"</p>
                                          </div>
                                      )}
                                </div>

                                {/* Footer */}
                                <div className="p-4 border-t border-slate-800 bg-[#0f172a] flex justify-between items-center shrink-0 z-20">
                                    <div className="flex items-center gap-3">
                                        <span className="text-sm font-medium text-slate-400">
                                           <span className="text-white font-bold">{selectedIntegrations.length}</span> apps selected
                                        </span>
                                        {selectedIntegrations.length > 0 && (
                                            <button onClick={() => setSelectedIntegrations([])} className="text-xs text-red-400 hover:text-red-300 hover:underline px-2 py-1 rounded hover:bg-red-500/10 transition-colors">
                                                Clear all
                                            </button>
                                        )}
                                    </div>
                                    <button 
                                      onClick={() => setShowIntegrations(false)} 
                                      className="px-6 py-2.5 bg-vibrant-green hover:bg-emerald-500 text-navy-900 font-bold rounded-xl transition-all shadow-lg shadow-emerald-900/20 hover:scale-105 active:scale-95 flex items-center gap-2"
                                    >
                                        <Check className="w-4 h-4" /> Done
                                    </button>
                                </div>
                            </div>
                        </div>,
                        document.body
                    )}

                    {/* File Attachment Pill */}
                    {attachedFiles.length > 0 && (
                        <div className="flex flex-wrap gap-2 mb-2 px-2 max-h-20 overflow-y-auto custom-scrollbar">
                            {attachedFiles.map((file, i) => (
                                <div key={i} className="flex items-center gap-2 px-3 py-1 bg-slate-800 border border-slate-700 rounded-full text-xs text-slate-300 animate-in fade-in zoom-in">
                                    <Paperclip className="w-3 h-3 text-vibrant-orange shrink-0" />
                                    <span className="max-w-[100px] truncate">{file.name}</span>
                                    <button onClick={() => removeFile(i)} className="hover:text-white shrink-0"><X className="w-3 h-3" /></button>
                                </div>
                            ))}
                        </div>
                    )}

                    <div className="relative flex items-center gap-2 bg-slate-900 border border-slate-800 rounded-2xl p-2 shadow-lg focus-within:border-slate-600 focus-within:ring-1 focus-within:ring-slate-600 transition-all">
                        <button 
                            id="tour-apps-lib"
                            onClick={() => setShowIntegrations(true)}
                            className={`p-2.5 rounded-xl transition-colors shrink-0 ${selectedIntegrations.length > 0 ? 'bg-vibrant-orange/10 text-vibrant-orange' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
                            title="Add Integration"
                        >
                            {selectedIntegrations.length > 0 ? (
                                <span className="text-xs font-bold w-5 h-5 flex items-center justify-center bg-vibrant-orange text-white rounded-full">{selectedIntegrations.length}</span>
                            ) : (
                                <LayoutGrid className="w-5 h-5" />
                            )}
                        </button>

                        <input 
                            type="file"
                            ref={fileInputRef}
                            className="hidden"
                            onChange={handleFileUpload}
                        />
                         <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="p-2.5 rounded-xl text-slate-400 hover:bg-slate-800 hover:text-white transition-colors shrink-0"
                            title="Attach File"
                        >
                            <Paperclip className="w-5 h-5" />
                        </button>

                        <input 
                            type="text" 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && executeWorkflowGeneration(input)}
                            placeholder={isListening ? "Listening..." : uiText.inputPlaceholder}
                            className="flex-1 bg-transparent border-none text-white placeholder:text-slate-500 text-sm focus:outline-none px-2 h-10 min-w-0"
                            disabled={isProcessing}
                        />

                        {/* VOICE BUTTON - PROMINENT */}
                        <button 
                            id="tour-voice-btn"
                            onClick={startListening}
                            className={`p-3 rounded-xl transition-all shadow-lg transform active:scale-95 shrink-0 ${
                                isListening 
                                ? 'bg-red-500 text-white animate-pulse shadow-red-500/30' 
                                : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700'
                            }`}
                            title="Voice Input"
                        >
                            {isListening ? <Mic className="w-5 h-5 animate-bounce" /> : <Mic className="w-5 h-5" />}
                        </button>

                        <button 
                            onClick={() => executeWorkflowGeneration(input)}
                            disabled={!input.trim() || isProcessing}
                            className="p-3 bg-vibrant-green hover:bg-emerald-500 disabled:opacity-50 disabled:hover:bg-vibrant-green text-navy-900 rounded-xl transition-all shadow-lg shadow-emerald-900/20 transform active:scale-95 shrink-0"
                        >
                            {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
                        </button>
                    </div>

                    <div className="text-center mt-3 flex items-center justify-center gap-2 text-[10px] text-slate-600 font-medium">
                        <MapPin className="w-3 h-3" /> Secure Enterprise Environment • AI can make mistakes.
                    </div>
                </div>
                </>
            )}
        </div>
      </div>

      {/* --- MODALS --- */}

      {/* CREATE AGENT MODAL */}
      {showCreateAgentModal && (
          <div className="absolute inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
              <div className="bg-slate-900 border border-slate-700 w-full max-w-md rounded-2xl p-6 shadow-2xl relative">
                  <button onClick={() => setShowCreateAgentModal(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X className="w-5 h-5"/></button>
                  <h3 className="text-xl font-bold text-white mb-1">Create Custom Agent</h3>
                  <p className="text-slate-400 text-sm mb-6">Define a specialized agent for your needs.</p>

                  <div className="space-y-4">
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase">Agent Name</label>
                          <input 
                              type="text" 
                              value={newAgentData.name}
                              onChange={e => setNewAgentData({...newAgentData, name: e.target.value})}
                              className="w-full mt-1 bg-slate-950 border border-slate-800 rounded-xl p-3 text-white text-sm focus:border-vibrant-green outline-none"
                              placeholder="e.g. Legal Assistant"
                          />
                      </div>
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase">Role / Instructions</label>
                          <textarea 
                              value={newAgentData.role}
                              onChange={e => setNewAgentData({...newAgentData, role: e.target.value})}
                              className="w-full mt-1 bg-slate-950 border border-slate-800 rounded-xl p-3 text-white text-sm focus:border-vibrant-green outline-none h-24 resize-none"
                              placeholder="Describe what this agent should do..."
                          />
                      </div>
                      <button 
                          onClick={handleCreateAgent}
                          disabled={!newAgentData.name}
                          className="w-full py-3 bg-vibrant-green text-navy-900 font-bold rounded-xl hover:bg-emerald-500 transition-colors disabled:opacity-50"
                      >
                          Create Agent
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* VISUAL WORKFLOW EDITOR MODAL */}
      {showVisualEditor && editorData && (
          <div className="absolute inset-0 z-[60] bg-slate-950 flex flex-col animate-in slide-in-from-bottom-10 duration-300">
              {/* Editor Header */}
              <div className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900">
                  <div className="flex items-center gap-3">
                      <div className="p-2 bg-vibrant-orange/10 rounded-lg"><Layers className="w-5 h-5 text-vibrant-orange"/></div>
                      <div>
                          <h3 className="text-white font-bold">Visual Workflow Editor</h3>
                          <p className="text-xs text-slate-400">{editorData.workflow_name || 'Untitled Workflow'}</p>
                      </div>
                      <span className="px-2 py-0.5 ml-2 bg-slate-800 rounded text-[10px] text-slate-400 border border-slate-700 hidden sm:inline-block">{editorData.trigger.type}</span>
                  </div>
                  <div className="flex items-center gap-3">
                      <button 
                          onClick={handleSaveEditor}
                          className="px-4 py-2 bg-vibrant-green text-navy-900 text-sm font-bold rounded-lg hover:bg-emerald-400 transition-colors flex items-center gap-2"
                      >
                          <Check className="w-4 h-4"/> <span className="hidden sm:inline">Save Changes</span>
                      </button>
                      <button onClick={() => setShowVisualEditor(false)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white">
                          <X className="w-5 h-5"/>
                      </button>
                  </div>
              </div>

              {/* Editor Content Grid */}
              <div className="flex-1 overflow-hidden grid grid-cols-1 md:grid-cols-12">
                  {/* Canvas Area (Left) */}
                  <div className="md:col-span-8 bg-[#0B1120] relative overflow-hidden bg-[linear-gradient(rgba(255,255,255,0.03)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.03)_1px,transparent_1px)] bg-[size:40px_40px]">
                      <div className="absolute inset-0 flex items-center justify-center p-10 overflow-y-auto">
                          <div className="flex flex-col items-center space-y-8 w-full max-w-lg">

                              {/* Trigger Node */}
                              <div 
                                onClick={() => setSelectedStepIndex(-1)} // -1 for trigger
                                className={`w-full p-4 rounded-xl border-2 transition-all cursor-pointer relative group ${selectedStepIndex === -1 ? 'bg-slate-800 border-vibrant-orange shadow-[0_0_20px_rgba(249,115,22,0.2)]' : 'bg-slate-900 border-slate-700 hover:border-slate-500'}`}
                              >
                                  <div className="text-[10px] font-bold text-slate-500 uppercase mb-2">TRIGGER</div>
                                  <div className="flex items-center gap-3">
                                      <div className="w-8 h-8 rounded-lg bg-vibrant-green/10 flex items-center justify-center text-vibrant-green"><Zap className="w-4 h-4"/></div>
                                      <div>
                                          <div className="font-bold text-white text-sm">{editorData.trigger.type}</div>
                                          <div className="text-xs text-slate-400">{editorData.trigger.frequency}</div>
                                      </div>
                                  </div>
                                  {/* Connector Line */}
                                  <div className="absolute top-full left-1/2 w-0.5 h-8 bg-slate-700 -translate-x-1/2 z-0"></div>
                              </div>

                              {/* Action Nodes */}
                              {editorData.actions.map((action, idx) => (
                                  <div key={idx} className="w-full relative group">
                                      <div 
                                        onClick={() => setSelectedStepIndex(idx)}
                                        className={`w-full p-4 rounded-xl border-2 transition-all cursor-pointer relative z-10 ${selectedStepIndex === idx ? 'bg-slate-800 border-blue-500 shadow-[0_0_20px_rgba(59,130,246,0.2)]' : 'bg-slate-900 border-slate-700 hover:border-slate-500'}`}
                                      >
                                          <div className="flex justify-between items-start mb-2">
                                              <div className="text-[10px] font-bold text-slate-500 uppercase">STEP {idx + 1}</div>
                                              <button onClick={(e) => { e.stopPropagation(); handleRemoveStep(idx); }} className="text-slate-600 hover:text-red-500"><Trash2 className="w-3 h-3"/></button>
                                          </div>
                                          <div className="flex items-center gap-3">
                                              <div className="w-8 h-8 rounded-lg bg-blue-500/10 flex items-center justify-center text-blue-500"><Bot className="w-4 h-4"/></div>
                                              <div className="flex-1 min-w-0">
                                                  <div className="font-bold text-white text-sm truncate">{action.action_type}</div>
                                                  <div className="text-xs text-vibrant-orange font-bold uppercase tracking-wider">{action.app}</div>
                                              </div>
                                          </div>
                                          <p className="mt-2 text-xs text-slate-400 line-clamp-2">{action.instructions}</p>
                                      </div>

                                      {/* Connector Line (except last) */}
                                      {idx !== editorData.actions.length - 1 && (
                                          <div className="absolute top-full left-1/2 w-0.5 h-8 bg-slate-700 -translate-x-1/2 z-0"></div>
                                      )}
                                  </div>
                              ))}

                              {/* Add Step Button */}
                              <button onClick={handleAddStep} className="w-8 h-8 rounded-full bg-slate-800 border border-slate-600 flex items-center justify-center hover:bg-slate-700 hover:border-slate-400 transition-all">
                                  <Plus className="w-4 h-4 text-slate-400"/>
                              </button>
                          </div>
                      </div>
                  </div>

                  {/* Configuration Panel (Right) */}
                  <div className={`md:col-span-4 bg-slate-900 border-l border-slate-800 flex flex-col absolute md:relative inset-y-0 right-0 w-80 md:w-auto transform transition-transform duration-300 ${selectedStepIndex !== null ? 'translate-x-0' : 'translate-x-full md:translate-x-0'} z-20`}>
                      <div className="p-4 border-b border-slate-800 bg-slate-900 flex justify-between items-center">
                          <h4 className="font-bold text-white text-sm">Configuration</h4>
                          <button onClick={() => setSelectedStepIndex(null)} className="md:hidden text-slate-400"><X className="w-4 h-4"/></button>
                      </div>

                      <div className="flex-1 overflow-y-auto p-4 space-y-6">
                          {selectedStepIndex === null ? (
                              <div className="text-center text-slate-500 py-10 hidden md:block">
                                  <MousePointerClick className="w-10 h-10 mx-auto mb-2 opacity-50"/>
                                  <p className="text-sm">Select a step to configure</p>
                              </div>
                          ) : selectedStepIndex === -1 ? (
                              // Trigger Config
                              <div className="space-y-4 animate-in fade-in">
                                  <div className="text-xs font-bold text-vibrant-green uppercase tracking-wider mb-2">TRIGGER SETTINGS</div>

                                  <div>
                                      <label className="text-xs text-slate-400 block mb-1">Trigger Type</label>
                                      <input 
                                        type="text" 
                                        value={editorData.trigger.type} 
                                        onChange={(e) => handleEditorTriggerChange('type', e.target.value)}
                                        className="w-full bg-slate-950 border border-slate-800 rounded-lg p-3 text-sm text-white focus:border-vibrant-green outline-none" 
                                      />
                                  </div>
                                  <div>
                                      <label className="text-xs text-slate-400 block mb-1">Frequency</label>
                                      <select
                                        value={editorData.trigger.frequency}
                                        onChange={(e) => handleEditorTriggerChange('frequency', e.target.value)}
                                        className="w-full bg-slate-950 border border-slate-800 rounded-lg p-3 text-sm text-white focus:border-vibrant-green outline-none"
                                      >
                                          <option value="Real-time">Real-time (Immediate)</option>
                                          <option value="Daily">Daily</option>
                                          <option value="Weekly">Weekly</option>
                                          <option value="Monthly">Monthly</option>
                                      </select>
                                  </div>
                                  <div>
                                      <label className="text-xs text-slate-400 block mb-1">Example Data (JSON)</label>
                                      <textarea 
                                        value={typeof editorData.trigger.example_data === 'string' ? editorData.trigger.example_data : JSON.stringify(editorData.trigger.example_data, null, 2)}
                                        onChange={(e) => handleEditorTriggerChange('example_data', e.target.value)}
                                        className="w-full h-32 bg-slate-950 border border-slate-800 rounded-lg p-3 text-xs font-mono text-slate-300 focus:border-vibrant-green outline-none resize-none"
                                      />
                                  </div>
                              </div>
                          ) : (
                              // Action Config
                              <div className="space-y-4 animate-in fade-in">
                                  <div className="text-xs font-bold text-blue-500 uppercase tracking-wider mb-2">ACTION SETTINGS</div>

                                  <div>
                                      <label className="text-xs text-slate-400 block mb-1">App / Service</label>
                                      <select
                                        value={editorData.actions[selectedStepIndex].app}
                                        onChange={(e) => handleEditorActionChange(selectedStepIndex, 'app', e.target.value)}
                                        className="w-full bg-slate-950 border border-slate-800 rounded-lg p-3 text-sm text-white focus:border-blue-500 outline-none"
                                      >
                                          {ALL_TOOLS.map(tool => <option key={tool} value={tool}>{tool}</option>)}
                                          <option value="System">System (Internal)</option>
                                      </select>
                                  </div>
                                  <div>
                                      <label className="text-xs text-slate-400 block mb-1">Action Type</label>
                                      <input 
                                        type="text" 
                                        value={editorData.actions[selectedStepIndex].action_type}
                                        onChange={(e) => handleEditorActionChange(selectedStepIndex, 'action_type', e.target.value)}
                                        className="w-full bg-slate-950 border border-slate-800 rounded-lg p-3 text-sm text-white focus:border-blue-500 outline-none"
                                      />
                                  </div>
                                  <div>
                                      <label className="text-xs text-slate-400 block mb-1">Instructions / Logic</label>
                                      <textarea 
                                        value={editorData.actions[selectedStepIndex].instructions}
                                        onChange={(e) => handleEditorActionChange(selectedStepIndex, 'instructions', e.target.value)}
                                        className="w-full h-32 bg-slate-950 border border-slate-800 rounded-lg p-3 text-sm text-slate-300 focus:border-blue-500 outline-none resize-none"
                                      />
                                  </div>

                                  <div className="pt-4 border-t border-slate-800">
                                      <div className="flex items-center justify-between">
                                          <span className="text-sm text-white">Auto-Integration</span>
                                          <div className={`w-10 h-5 rounded-full relative cursor-pointer transition-colors ${editorData.actions[selectedStepIndex].auto_integration ? 'bg-green-500' : 'bg-slate-700'}`} onClick={() => handleEditorActionChange(selectedStepIndex, 'auto_integration', (!editorData.actions[selectedStepIndex].auto_integration).toString())}>
                                              <div className={`w-3 h-3 bg-white rounded-full absolute top-1 transition-all ${editorData.actions[selectedStepIndex].auto_integration ? 'left-6' : 'left-1'}`}></div>
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          )}
                      </div>
                  </div>
              </div>
          </div>
      )}

    </div>
  );
};
